-- Part 3: Verses for Chapters 10 through 18 (341 Verses)
INSERT INTO public.gita_verses (id, chapter_number, verse_number, verse_order, external_id, sanskrit, transliteration, word_meanings, word_meanings_raw) VALUES
('10f6398d-c4dc-5da9-b592-8ba3dca1afdf'::uuid, 10, 1, 373, 373, 'श्री भगवानुवाच

भूय एव महाबाहो श्रृणु मे परमं वचः।

यत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया।।10.1।।', 'śhrī bhagavān uvācha
bhūya eva mahā-bāho śhṛiṇu me paramaṁ vachaḥ
yatte ’haṁ prīyamāṇāya vakṣhyāmi hita-kāmyayā', '[{"word":"śhrī","meaning":"bhagavān uvācha—the Blessed Lord said"},{"word":"bhūyaḥ","meaning":"again"},{"word":"eva","meaning":"verily"},{"word":"mahā","meaning":"bāho—mighty armed one"},{"word":"śhṛiṇu","meaning":"hear"},{"word":"me","meaning":"my"},{"word":"paramam","meaning":"divine"},{"word":"vachaḥ","meaning":"teachings"},{"word":"yat","meaning":"which"},{"word":"te","meaning":"to you"},{"word":"aham","meaning":"I"},{"word":"prīyamāṇāya","meaning":"you are my beloved confidant"},{"word":"vakṣhyāmi","meaning":"say"},{"word":"hita","meaning":"kāmyayā—for desiring your welfare"}]'::jsonb, 'śhrī-bhagavān uvācha—the Blessed Lord said; bhūyaḥ—again; eva—verily; mahā-bāho—mighty armed one; śhṛiṇu—hear; me—my; paramam—divine; vachaḥ—teachings; yat—which; te—to you; aham—I; prīyamāṇāya—you are my beloved confidant; vakṣhyāmi—say; hita-kāmyayā—for desiring your welfare'),
('034c4f59-c649-5d7a-bfc6-0c5e6523576e'::uuid, 10, 2, 374, 374, 'न मे विदुः सुरगणाः प्रभवं न महर्षयः।

अहमादिर्हि देवानां महर्षीणां च सर्वशः।।10.2।।', 'na me viduḥ sura-gaṇāḥ prabhavaṁ na maharṣhayaḥ
aham ādir hi devānāṁ maharṣhīṇāṁ cha sarvaśhaḥ', '[{"word":"na","meaning":"neither"},{"word":"me","meaning":"my"},{"word":"viduḥ","meaning":"know"},{"word":"sura","meaning":"gaṇāḥ—the celestial gods"},{"word":"prabhavam","meaning":"origin"},{"word":"na","meaning":"nor"},{"word":"mahā","meaning":"ṛiṣhayaḥ—the great sages"},{"word":"aham","meaning":"I"},{"word":"ādiḥ","meaning":"the source"},{"word":"hi","meaning":"certainly"},{"word":"devānām","meaning":"of the celestial gods"},{"word":"mahā","meaning":"ṛiṣhīṇām—of the great seers"},{"word":"cha","meaning":"also"},{"word":"sarvaśhaḥ","meaning":"in every way"}]'::jsonb, 'na—neither; me—my; viduḥ—know; sura-gaṇāḥ—the celestial gods; prabhavam—origin; na—nor; mahā-ṛiṣhayaḥ—the great sages; aham—I; ādiḥ—the source; hi—certainly; devānām—of the celestial gods; mahā-ṛiṣhīṇām—of the great seers; cha—also; sarvaśhaḥ—in every way'),
('ad968164-2c65-5857-a67a-532cc4fa231c'::uuid, 10, 3, 375, 375, 'यो मामजमनादिं च वेत्ति लोकमहेश्वरम्।

असम्मूढः स मर्त्येषु सर्वपापैः प्रमुच्यते।।10.3।।', 'yo māmajam anādiṁ cha vetti loka-maheśhvaram
asammūḍhaḥ sa martyeṣhu sarva-pāpaiḥ pramuchyate', '[{"word":"verseyaḥ","meaning":"who"},{"word":"mām","meaning":"me"},{"word":"ajam","meaning":"unborn"},{"word":"anādim","meaning":"beginningless"},{"word":"cha","meaning":"and"},{"word":"vetti","meaning":"know"},{"word":"loka","meaning":"of the universe"},{"word":"mahā","meaning":"īśhvaram—the Supreme Lord"},{"word":"asammūḍhaḥ","meaning":"undeluded"},{"word":"saḥ","meaning":"they"},{"word":"martyeṣhu","meaning":"among mortals"},{"word":"sarva","meaning":"pāpaiḥ—from all evils"},{"word":"pramuchyate","meaning":"are freed from-3"}]'::jsonb, 'verseyaḥ—who; mām—me; ajam—unborn; anādim—beginningless; cha—and; vetti—know; loka—of the universe; mahā-īśhvaram—the Supreme Lord; asammūḍhaḥ—undeluded; saḥ—they; martyeṣhu—among mortals; sarva-pāpaiḥ—from all evils; pramuchyate—are freed from-3'),
('5ed9ce8d-5da8-5a65-b6e1-5ae4baaa07ca'::uuid, 10, 4, 376, 376, 'बुद्धिर्ज्ञानमसंमोहः क्षमा सत्यं दमः शमः।

सुखं दुःखं भवोऽभावो भयं चाभयमेव च।।10.4।।', 'buddhir jñānam asammohaḥ kṣhamā satyaṁ damaḥ śhamaḥ
sukhaṁ duḥkhaṁ bhavo ’bhāvo bhayaṁ chābhayameva cha', '[{"word":"buddhiḥ","meaning":"intellect"},{"word":"jñānam","meaning":"knowledge"},{"word":"asammohaḥ","meaning":"clarity of thought"},{"word":"kṣhamā","meaning":"forgiveness"},{"word":"satyam","meaning":"truthfulness"},{"word":"damaḥ","meaning":"control over the senses"},{"word":"śhamaḥ","meaning":"control of the mind"},{"word":"sukham","meaning":"joy"},{"word":"duḥkham","meaning":"sorrow"},{"word":"bhavaḥ","meaning":"birth"},{"word":"abhāvaḥ","meaning":"death"},{"word":"bhayam","meaning":"fear"},{"word":"cha","meaning":"and"},{"word":"abhayam","meaning":"courage"},{"word":"eva","meaning":"certainly"},{"word":"cha","meaning":"and"}]'::jsonb, 'buddhiḥ—intellect; jñānam—knowledge; asammohaḥ—clarity of thought; kṣhamā—forgiveness; satyam—truthfulness; damaḥ—control over the senses; śhamaḥ—control of the mind; sukham—joy; duḥkham—sorrow; bhavaḥ—birth; abhāvaḥ—death; bhayam—fear; cha—and; abhayam—courage; eva—certainly; cha—and;'),
('13ca1067-53c0-578b-a7fd-8c8d1eab20aa'::uuid, 10, 5, 377, 377, 'अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः।

भवन्ति भावा भूतानां मत्त एव पृथग्विधाः।।10.5।।', 'ahiṁsā   samatā  tuṣṭis tapo dānaṁ   yaśo    ''yaśaḥ  bhavanti    bhāvā   bhūtānāṁ    matta   eva pṛthag-vidhāḥ', '[{"word":"ahiṁsā","meaning":"nonviolence"},{"word":"samatā","meaning":"equilibrium"},{"word":"tuṣṭiḥ","meaning":"satisfaction"},{"word":"tapaḥ","meaning":"penance"},{"word":"dānam","meaning":"charity"},{"word":"yaśaḥ","meaning":"fame"},{"word":"ayaśaḥ","meaning":"infamy"},{"word":"bhavanti","meaning":"become"},{"word":"bhāvāḥ","meaning":"natures"},{"word":"bhūtānām","meaning":"of living  entities"},{"word":"mattaḥ","meaning":"from Me"},{"word":"eva","meaning":"certainly"},{"word":"pṛthakvidhāḥ","meaning":"differently    arranged."}]'::jsonb, 'ahiṁsā—nonviolence;    samatā—equilibrium; tuṣṭiḥ—satisfaction;    tapaḥ—penance;  dānam—charity;  yaśaḥ—fame; ayaśaḥ—infamy;  bhavanti—become;    bhāvāḥ—natures;     bhūtānām—of living  entities;   mattaḥ—from Me; eva—certainly;  pṛthakvidhāḥ—differently    arranged.'),
('08e901be-ad05-5cad-a38f-b24dd44d7d25'::uuid, 10, 6, 378, 378, 'महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा।

मद्भावा मानसा जाता येषां लोक इमाः प्रजाः।।10.6।।', 'maharṣhayaḥ sapta pūrve chatvāro manavas tathā
mad-bhāvā mānasā jātā yeṣhāṁ loka imāḥ prajāḥ', '[{"word":"mahā","meaning":"ṛiṣhayaḥ—the great Sages"},{"word":"sapta","meaning":"seven"},{"word":"pūrve","meaning":"before"},{"word":"chatvāraḥ","meaning":"four"},{"word":"manavaḥ","meaning":"Manus"},{"word":"tathā","meaning":"also"},{"word":"mat bhāvāḥ","meaning":"are born from me"},{"word":"mānasāḥ","meaning":"mind"},{"word":"jātāḥ","meaning":"born"},{"word":"yeṣhām","meaning":"from them"},{"word":"loke","meaning":"in the world"},{"word":"imāḥ","meaning":"all these"},{"word":"prajāḥ","meaning":"people"}]'::jsonb, 'mahā-ṛiṣhayaḥ—the great Sages; sapta—seven; pūrve—before; chatvāraḥ—four; manavaḥ—Manus; tathā—also; mat bhāvāḥ—are born from me; mānasāḥ—mind; jātāḥ—born; yeṣhām—from them; loke—in the world; imāḥ—all these; prajāḥ—people'),
('64279be0-d27f-5ad6-9319-246653e6c66d'::uuid, 10, 7, 379, 379, 'एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः।

सोऽविकम्पेन योगेन युज्यते नात्र संशयः।।10.7।।', 'etāṁ vibhūtiṁ yogaṁ cha mama yo vetti tattvataḥ
so ’vikampena yogena yujyate nātra sanśhayaḥ', '[{"word":"etām","meaning":"these"},{"word":"vibhūtim","meaning":"glories"},{"word":"yogam","meaning":"divine powers"},{"word":"cha","meaning":"and"},{"word":"mama","meaning":"my"},{"word":"yaḥ","meaning":"those who"},{"word":"vetti","meaning":"know"},{"word":"tattvataḥ","meaning":"in truth"},{"word":"saḥ","meaning":"they"},{"word":"avikalpena","meaning":"unwavering"},{"word":"yogena","meaning":"in bhakti yog"},{"word":"yujyate","meaning":"becomes united"},{"word":"na","meaning":"never"},{"word":"atra","meaning":"here"},{"word":"sanśhayaḥ","meaning":"doubt"}]'::jsonb, 'etām—these; vibhūtim—glories; yogam—divine powers; cha—and; mama—my; yaḥ—those who; vetti—know; tattvataḥ—in truth; saḥ—they; avikalpena—unwavering; yogena—in bhakti yog; yujyate—becomes united; na—never; atra—here; sanśhayaḥ—doubt'),
('4869a956-b4ea-5734-bcf8-62320e674dc6'::uuid, 10, 8, 380, 380, 'अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते।

इति मत्वा भजन्ते मां बुधा भावसमन्विताः।।10.8।।', 'ahaṁ sarvasya prabhavo mattaḥ sarvaṁ pravartate
iti matvā bhajante māṁ budhā bhāva-samanvitāḥ', '[{"word":"aham","meaning":"I"},{"word":"sarvasya","meaning":"of all creation"},{"word":"prabhavaḥ","meaning":"the origin of"},{"word":"mattaḥ","meaning":"from me"},{"word":"sarvam","meaning":"everything"},{"word":"pravartate","meaning":"proceeds"},{"word":"iti","meaning":"thus"},{"word":"matvā","meaning":"having known"},{"word":"bhajante","meaning":"worship"},{"word":"mām","meaning":"me"},{"word":"budhāḥ","meaning":"the wise"},{"word":"bhāva","meaning":"samanvitāḥ—endowed with great faith and devotion"}]'::jsonb, 'aham—I; sarvasya—of all creation; prabhavaḥ—the origin of; mattaḥ—from me; sarvam—everything; pravartate—proceeds; iti—thus; matvā—having known; bhajante—worship; mām—me; budhāḥ—the wise; bhāva-samanvitāḥ—endowed with great faith and devotion'),
('0f2ba58c-f684-5bd5-9040-87d1f64c85b7'::uuid, 10, 9, 381, 381, 'मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम्।

कथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च।।10.9।।', 'mach-chittā mad-gata-prāṇā bodhayantaḥ parasparam
kathayantaśh cha māṁ nityaṁ tuṣhyanti cha ramanti cha', '[{"word":"mat","meaning":"chittāḥ—those with minds fixed on me"},{"word":"mat","meaning":"gata-prāṇāḥ—those who have surrendered their lives to me"},{"word":"bodhayantaḥ","meaning":"enlightening (with divine knowledge of God)"},{"word":"parasparam","meaning":"one another"},{"word":"kathayantaḥ","meaning":"speaking"},{"word":"cha","meaning":"and"},{"word":"mām","meaning":"about me"},{"word":"nityam","meaning":"continously"},{"word":"tuṣhyanti","meaning":"satisfaction"},{"word":"cha","meaning":"and"},{"word":"ramanti","meaning":"(they) delight"},{"word":"cha","meaning":"also"}]'::jsonb, 'mat-chittāḥ—those with minds fixed on me; mat-gata-prāṇāḥ—those who have surrendered their lives to me; bodhayantaḥ—enlightening (with divine knowledge of God); parasparam—one another; kathayantaḥ—speaking; cha—and; mām—about me; nityam—continously; tuṣhyanti—satisfaction; cha—and; ramanti—(they) delight; cha—also'),
('7f6ea195-976c-5024-a29c-6245f8dba5fd'::uuid, 10, 10, 382, 382, 'तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम्।

ददामि बुद्धियोगं तं येन मामुपयान्ति ते।।10.10।।', 'teṣhāṁ satata-yuktānāṁ bhajatāṁ prīti-pūrvakam
dadāmi buddhi-yogaṁ taṁ yena mām upayānti te', '[{"word":"teṣhām","meaning":"to them"},{"word":"satata","meaning":"yuktānām—ever steadfast"},{"word":"bhajatām","meaning":"who engage in devotion"},{"word":"prīti","meaning":"pūrvakam—with love"},{"word":"dadāmi","meaning":"I give"},{"word":"buddhi","meaning":"yogam—divine knowledge"},{"word":"tam","meaning":"that"},{"word":"yena","meaning":"by which"},{"word":"mām","meaning":"to me"},{"word":"upayānti","meaning":"come"},{"word":"te","meaning":"they"}]'::jsonb, 'teṣhām—to them; satata-yuktānām—ever steadfast; bhajatām—who engage in devotion; prīti-pūrvakam—with love; dadāmi—I give; buddhi-yogam—divine knowledge; tam—that; yena—by which; mām—to me; upayānti—come; te—they'),
('0bec73d2-b93d-5aff-a187-b5bd459758ad'::uuid, 10, 11, 383, 383, 'तेषामेवानुकम्पार्थमहमज्ञानजं तमः।

नाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता।।10.11।।', 'teṣhām evānukampārtham aham ajñāna-jaṁ tamaḥ
nāśhayāmyātma-bhāva-stho jñāna-dīpena bhāsvatā', '[{"word":"teṣhām","meaning":"for them"},{"word":"eva","meaning":"only"},{"word":"anukampā","meaning":"artham—out of compassion"},{"word":"aham","meaning":"I"},{"word":"ajñāna","meaning":"jam—born of ignorance"},{"word":"tamaḥ","meaning":"darkness"},{"word":"nāśhayāmi","meaning":"destroy"},{"word":"ātma","meaning":"bhāva—within their hearts"},{"word":"sthaḥ","meaning":"dwelling"},{"word":"jñāna","meaning":"of knowledge"},{"word":"dīpena","meaning":"with the lamp"},{"word":"bhāsvatā","meaning":"luminous"}]'::jsonb, 'teṣhām—for them; eva—only; anukampā-artham—out of compassion; aham—I; ajñāna-jam—born of ignorance; tamaḥ—darkness; nāśhayāmi—destroy; ātma-bhāva—within their hearts; sthaḥ—dwelling; jñāna—of knowledge; dīpena—with the lamp; bhāsvatā—luminous'),
('5cb8a5d5-415c-535a-b218-ff85e7ac02e1'::uuid, 10, 12, 384, 384, 'अर्जुन उवाच

परं ब्रह्म परं धाम पवित्रं परमं भवान्।

पुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम्।।10.12।।', 'arjuna uvācha
paraṁ brahma paraṁ dhāma pavitraṁ paramaṁ bhavān
puruṣhaṁ śhāśhvataṁ divyam ādi-devam ajaṁ vibhum', '[{"word":"arjunaḥ uvācha","meaning":"Arjun said"},{"word":"param","meaning":"Supreme"},{"word":"brahma","meaning":"Brahman"},{"word":"param","meaning":"Supreme"},{"word":"dhāma","meaning":"Abode"},{"word":"pavitram","meaning":"purifier"},{"word":"paramam","meaning":"Supreme"},{"word":"bhavān","meaning":"you"},{"word":"puruṣham","meaning":"personality"},{"word":"śhāśhvatam","meaning":"Eternal"},{"word":"divyam","meaning":"Divine"},{"word":"ādi","meaning":"devam—the Primal Being"},{"word":"ajam","meaning":"the Unborn"},{"word":"vibhum","meaning":"the Great"}]'::jsonb, 'arjunaḥ uvācha—Arjun said; param—Supreme; brahma—Brahman; param—Supreme; dhāma—Abode; pavitram—purifier; paramam—Supreme; bhavān—you; puruṣham—personality; śhāśhvatam—Eternal; divyam—Divine; ādi-devam—the Primal Being; ajam—the Unborn; vibhum—the Great;'),
('7d5e5da9-7ea0-5746-a68e-0b9b66127198'::uuid, 10, 13, 385, 385, 'आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा।

असितो देवलो व्यासः स्वयं चैव ब्रवीषि मे।।10.13।।', 'āhus tvām ṛiṣhayaḥ sarve devarṣhir nāradas tathā
asito devalo vyāsaḥ svayaṁ chaiva bravīṣhi me', '[{"word":"āhuḥ","meaning":"(they) declare"},{"word":"tvām","meaning":"you"},{"word":"ṛiṣhayaḥ","meaning":"sages"},{"word":"sarve","meaning":"all"},{"word":"deva","meaning":"ṛiṣhiḥ-nāradaḥ—devarṣhi Narad"},{"word":"tathā","meaning":"also"},{"word":"asitaḥ","meaning":"Asit"},{"word":"devalaḥ","meaning":"Deval"},{"word":"vyāsaḥ","meaning":"Vyās"},{"word":"svayam","meaning":"personally"},{"word":"cha","meaning":"and"},{"word":"eva","meaning":"even"},{"word":"bravīṣhī","meaning":"you are declaring"},{"word":"me","meaning":"to me"}]'::jsonb, 'āhuḥ—(they) declare; tvām—you; ṛiṣhayaḥ—sages; sarve—all; deva-ṛiṣhiḥ-nāradaḥ—devarṣhi Narad; tathā—also; asitaḥ—Asit; devalaḥ—Deval; vyāsaḥ—Vyās; svayam—personally; cha—and; eva—even; bravīṣhī—you are declaring; me—to me'),
('fe918ed7-1928-5440-989d-d37ff9a912e4'::uuid, 10, 14, 386, 386, 'सर्वमेतदृतं मन्ये यन्मां वदसि केशव।

न हि ते भगवन् व्यक्ितं विदुर्देवा न दानवाः।।10.14।।', 'sarvam etad ṛitaṁ manye yan māṁ vadasi keśhava
na hi te bhagavan vyaktiṁ vidur devā na dānavāḥ', '[{"word":"sarvam","meaning":"everything"},{"word":"etat","meaning":"this"},{"word":"ṛitam","meaning":"truth"},{"word":"manye","meaning":"I accept"},{"word":"yat","meaning":"which"},{"word":"mām","meaning":"me"},{"word":"vadasi","meaning":"you tell"},{"word":"keśhava","meaning":"Shree Krishna, the killer of the demon named Keshi"},{"word":"na","meaning":"neither"},{"word":"hi","meaning":"verily"},{"word":"te","meaning":"your"},{"word":"bhagavan","meaning":"the Supreme Lord"},{"word":"vyaktim","meaning":"personality"},{"word":"viduḥ","meaning":"can understand"},{"word":"devāḥ","meaning":"the celestial gods"},{"word":"na","meaning":"nor"},{"word":"dānavāḥ","meaning":"the demons"}]'::jsonb, 'sarvam—everything; etat—this; ṛitam—truth; manye—I accept; yat—which; mām—me; vadasi—you tell; keśhava—Shree Krishna, the killer of the demon named Keshi; na—neither; hi—verily; te—your; bhagavan—the Supreme Lord; vyaktim—personality; viduḥ—can understand; devāḥ—the celestial gods; na—nor; dānavāḥ—the demons'),
('94df8fad-9c4a-5eb1-a40a-0314766bdfa4'::uuid, 10, 15, 387, 387, 'स्वयमेवात्मनाऽत्मानं वेत्थ त्वं पुरुषोत्तम।

भूतभावन भूतेश देवदेव जगत्पते।।10.15।।', 'swayam evātmanātmānaṁ vettha tvaṁ puruṣhottama
bhūta-bhāvana bhūteśha deva-deva jagat-pate', '[{"word":"swayam","meaning":"yourself"},{"word":"eva","meaning":"indeed"},{"word":"ātmanā","meaning":"by yourself"},{"word":"ātmānam","meaning":"yourself"},{"word":"vettha","meaning":"know"},{"word":"tvam","meaning":"you"},{"word":"puruṣha","meaning":"uttama—the Supreme Personality"},{"word":"bhūta","meaning":"bhāvana—the Creator of all beings"},{"word":"bhūta","meaning":"īśha—the Lord of everything"},{"word":"deva","meaning":"deva—the God of gods"},{"word":"jagat","meaning":"pate—the Lord of the universe"}]'::jsonb, 'swayam—yourself; eva—indeed; ātmanā—by yourself; ātmānam—yourself; vettha—know; tvam—you; puruṣha-uttama—the Supreme Personality; bhūta-bhāvana—the Creator of all beings; bhūta-īśha—the Lord of everything; deva-deva—the God of gods; jagat-pate—the Lord of the universe'),
('3eff04d5-6ded-56cc-86bb-7627961bbb80'::uuid, 10, 16, 388, 388, 'वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः।

याभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि।।10.16।।', 'vaktum arhasyaśheṣheṇa divyā hyātma-vibhūtayaḥ
yābhir vibhūtibhir lokān imāṁs tvaṁ vyāpya tiṣhṭhasi', '[{"word":"vaktum","meaning":"to describe"},{"word":"arhasi","meaning":"please do"},{"word":"aśheṣheṇa","meaning":"completely"},{"word":"divyāḥ","meaning":"divine"},{"word":"hi","meaning":"indeed"},{"word":"ātma","meaning":"your own"},{"word":"vibhūtayaḥ","meaning":"opulences"},{"word":"yābhiḥ","meaning":"by which"},{"word":"vibhūtibhiḥ","meaning":"opulences"},{"word":"lokān","meaning":"all worlds"},{"word":"imān","meaning":"these"},{"word":"tvam","meaning":"you"},{"word":"vyāpya","meaning":"pervade"},{"word":"tiṣhṭhasi","meaning":"reside"}]'::jsonb, 'vaktum—to describe; arhasi—please do; aśheṣheṇa—completely; divyāḥ—divine; hi—indeed; ātma—your own; vibhūtayaḥ—opulences; yābhiḥ—by which; vibhūtibhiḥ—opulences; lokān—all worlds; imān—these; tvam—you; vyāpya—pervade; tiṣhṭhasi—reside;'),
('d99a8d0d-9ee8-550d-905b-0c430d76d324'::uuid, 10, 17, 389, 389, 'कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन्।

केषु केषु च भावेषु चिन्त्योऽसि भगवन्मया।।10.17।।', 'kathaṁ vidyām ahaṁ yogins tvāṁ sadā parichintayan
