INSERT INTO public.gita_verses (id, chapter_number, verse_number, verse_order, external_id, sanskrit, transliteration, word_meanings, word_meanings_raw) VALUES
('d6a36d9f-78dc-5610-97be-4c0756c3c0b2'::uuid, 12, 4, 473, 473, 'संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः।ते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः।।12.4।।', 'sanniyamyendriya-grāmaṁ  sarvatra    sama-buddhayaḥ  te  prāpnuvanti mām eva sarva-bhūta-hite    ratāḥ', '[{"word":"sanniyamya","meaning":"controlling"},{"word":"indriya","meaning":"grāmam—all  the senses"},{"word":"sarvatra","meaning":"everywhere"},{"word":"sama","meaning":"buddayaḥ—equally  disposed"},{"word":"te","meaning":"they"},{"word":"prāpnuvanti","meaning":"achieve"},{"word":"mām","meaning":"unto    Me"},{"word":"eva","meaning":"certainly"},{"word":"sarva","meaning":"bhūtahite—all living  entities''   welfare"},{"word":"ratāḥ","meaning":"engaged."}]'::jsonb, 'sanniyamya-controlling;    indriya-grāmam—all  the senses; sarvatra—everywhere;     sama-buddayaḥ—equally  disposed;   te-they;    prāpnuvanti—achieve;    mām—unto    Me; eva—certainly;  sarva-bhūtahite—all living  entities''   welfare;    ratāḥ—engaged.'),
('579f4b38-2ad4-5f54-b09d-78a3ab3550d2'::uuid, 12, 5, 474, 474, 'क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम्।

अव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते।।12.5।।', 'kleśho ’dhikataras teṣhām avyaktāsakta-chetasām
avyaktā hi gatir duḥkhaṁ dehavadbhir avāpyate', '[{"word":"kleśhaḥ","meaning":"tribulations"},{"word":"adhika","meaning":"taraḥ—full of"},{"word":"teṣhām","meaning":"of those"},{"word":"avyakta","meaning":"to the unmanifest"},{"word":"āsakta","meaning":"attached"},{"word":"chetasām","meaning":"whose minds"},{"word":"avyaktā","meaning":"the unmanifest"},{"word":"hi","meaning":"indeed"},{"word":"gatiḥ","meaning":"path"},{"word":"duḥkham","meaning":"exceeding difficulty"},{"word":"deha","meaning":"vadbhiḥ—for the embodied"},{"word":"avāpyate","meaning":"is reached"}]'::jsonb, 'kleśhaḥ—tribulations; adhika-taraḥ—full of; teṣhām—of those; avyakta—to the unmanifest; āsakta—attached; chetasām—whose minds; avyaktā—the unmanifest; hi—indeed; gatiḥ—path; duḥkham—exceeding difficulty; deha-vadbhiḥ—for the embodied; avāpyate—is reached'),
('0a2b22d9-aecb-5774-9032-a79648cafb3b'::uuid, 12, 6, 475, 475, 'ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः।अनन्येनैव योगेन मां ध्यायन्त उपासते।।12.6।।', 'ye tu sarvāṇi karmāṇi mayi sannyasya mat-paraḥ
ananyenaiva yogena māṁ dhyāyanta upāsate', '[{"word":"ye","meaning":"who"},{"word":"tu","meaning":"but"},{"word":"sarvāṇi","meaning":"all"},{"word":"karmāṇi","meaning":"actions"},{"word":"mayi","meaning":"to me"},{"word":"sannyasya","meaning":"dedicating"},{"word":"mat","meaning":"paraḥ—regarding me as the Supreme goal"},{"word":"ananyena","meaning":"exclusively"},{"word":"eva","meaning":"certainly"},{"word":"yogena","meaning":"with devotion"},{"word":"mām","meaning":"me"},{"word":"dhyāyantaḥ","meaning":"meditating"},{"word":"upāsate","meaning":"worship"}]'::jsonb, 'ye—who; tu—but; sarvāṇi—all; karmāṇi—actions; mayi—to me; sannyasya—dedicating; mat-paraḥ—regarding me as the Supreme goal; ananyena—exclusively; eva—certainly; yogena—with devotion; mām—me; dhyāyantaḥ—meditating; upāsate—worship;'),
('67e5f4ad-737f-5979-8ef3-64014b903963'::uuid, 12, 7, 476, 476, 'तेषामहं समुद्धर्ता मृत्युसंसारसागरात्।भवामि नचिरात्पार्थ मय्यावेशितचेतसाम्।।12.7।।', 'teṣhām ahaṁ samuddhartā mṛityu-saṁsāra-sāgarāt
bhavāmi na chirāt pārtha mayy āveśhita-chetasām', '[{"word":"teṣhām","meaning":"of those"},{"word":"aham","meaning":"I"},{"word":"samuddhartā","meaning":"the deliverer"},{"word":"mṛityu","meaning":"saṁsāra-sāgarāt—from the ocean of birth and death"},{"word":"bhavāmi","meaning":"(I) become"},{"word":"na","meaning":"not"},{"word":"chirāt","meaning":"after a long time"},{"word":"pārtha","meaning":"Arjun, the son of Pritha"},{"word":"mayi","meaning":"with me"},{"word":"āveśhita chetasām","meaning":"of those whose consciousness is united"}]'::jsonb, 'teṣhām—of those; aham—I; samuddhartā—the deliverer; mṛityu-saṁsāra-sāgarāt—from the ocean of birth and death; bhavāmi—(I) become; na—not; chirāt—after a long time; pārtha—Arjun, the son of Pritha; mayi—with me; āveśhita chetasām—of those whose consciousness is united'),
('18a70a01-bf31-5b20-974d-9eb9a2551d2d'::uuid, 12, 8, 477, 477, 'मय्येव मन आधत्स्व मयि बुद्धिं निवेशय।निवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः।।12.8।।', 'mayy eva mana ādhatsva mayi buddhiṁ niveśhaya
nivasiṣhyasi mayy eva ata ūrdhvaṁ na sanśhayaḥ', '[{"word":"mayi","meaning":"on me"},{"word":"eva","meaning":"alone"},{"word":"manaḥ","meaning":"mind"},{"word":"ādhatsva","meaning":"fix"},{"word":"mayi","meaning":"on me"},{"word":"buddhim","meaning":"intellect"},{"word":"niveśhaya","meaning":"surrender"},{"word":"nivasiṣhyasi","meaning":"you shall always live"},{"word":"mayi","meaning":"in me"},{"word":"eva","meaning":"alone"},{"word":"ataḥ ūrdhvam","meaning":"thereafter"},{"word":"na","meaning":"not"},{"word":"sanśhayaḥ","meaning":"doubt"}]'::jsonb, 'mayi—on me; eva—alone; manaḥ—mind; ādhatsva—fix; mayi—on me; buddhim—intellect; niveśhaya—surrender; nivasiṣhyasi—you shall always live; mayi—in me; eva—alone; ataḥ ūrdhvam—thereafter; na—not; sanśhayaḥ—doubt'),
('6ef0f631-b1c8-5809-96f3-33ee56f47a55'::uuid, 12, 9, 478, 478, 'अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम्।अभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय।।12.9।।', 'atha chittaṁ samādhātuṁ na śhaknoṣhi mayi sthiram
abhyāsa-yogena tato mām ichchhāptuṁ dhanañjaya', '[{"word":"atha","meaning":"if"},{"word":"chittam","meaning":"mind"},{"word":"samādhātum","meaning":"to fix"},{"word":"na śhaknoṣhi","meaning":"(you) are unable"},{"word":"mayi","meaning":"on me"},{"word":"sthiram","meaning":"steadily"},{"word":"abhyāsa","meaning":"yogena—by uniting with God through repeated practice"},{"word":"tataḥ","meaning":"then"},{"word":"mām","meaning":"me"},{"word":"ichchhā","meaning":"desire"},{"word":"āptum","meaning":"to attain"},{"word":"dhanañjaya","meaning":"Arjun, the conqueror of wealth"}]'::jsonb, 'atha—if; chittam—mind; samādhātum—to fix; na śhaknoṣhi—(you) are unable; mayi—on me; sthiram—steadily; abhyāsa-yogena—by uniting with God through repeated practice; tataḥ—then; mām—me; ichchhā—desire; āptum—to attain; dhanañjaya—Arjun, the conqueror of wealth'),
('5deb16c4-4ee5-5bf4-a8b0-ba44108c0633'::uuid, 12, 10, 479, 479, 'अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव।मदर्थमपि कर्माणि कुर्वन् सिद्धिमवाप्स्यसि।।12.10।।', 'abhyāse ’py asamartho ’si mat-karma-paramo bhava
mad-artham api karmāṇi kurvan siddhim avāpsyasi', '[{"word":"abhyāse","meaning":"in practice"},{"word":"api","meaning":"if"},{"word":"asamarthaḥ","meaning":"unable"},{"word":"asi","meaning":"you"},{"word":"mat","meaning":"karma paramaḥ—devotedly work for me"},{"word":"bhava","meaning":"be"},{"word":"mat","meaning":"artham—for my sake"},{"word":"api","meaning":"also"},{"word":"karmāṇi","meaning":"work"},{"word":"kurvan","meaning":"performing"},{"word":"siddhim","meaning":"perfection"},{"word":"avāpsyasi","meaning":"you shall achieve"}]'::jsonb, 'abhyāse—in practice; api—if; asamarthaḥ—unable; asi—you; mat-karma paramaḥ—devotedly work for me; bhava—be; mat-artham—for my sake; api—also; karmāṇi—work; kurvan—performing; siddhim—perfection; avāpsyasi—you shall achieve'),
('da0bd3d1-5dbb-553e-a45e-8d1fd05111c3'::uuid, 12, 11, 480, 480, 'अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः।सर्वकर्मफलत्यागं ततः कुरु यतात्मवान्।।12.11।।', 'athaitad apy aśhakto ’si kartuṁ mad-yogam āśhritaḥ
sarva-karma-phala-tyāgaṁ tataḥ kuru yatātmavān', '[{"word":"atha","meaning":"if"},{"word":"etat","meaning":"this"},{"word":"api","meaning":"even"},{"word":"aśhaktaḥ","meaning":"unable"},{"word":"asi","meaning":"you are"},{"word":"kartum","meaning":"to work"},{"word":"mad","meaning":"yogam—with devotion to me"},{"word":"āśhritaḥ","meaning":"taking refuge"},{"word":"sarva","meaning":"karma—of all actions"},{"word":"phala","meaning":"tyāgam—to renounce the fruits"},{"word":"tataḥ","meaning":"then"},{"word":"kuru","meaning":"do"},{"word":"yata","meaning":"ātma-vān—be situated in the self"}]'::jsonb, 'atha—if; etat—this; api—even; aśhaktaḥ—unable; asi—you are; kartum—to work; mad-yogam—with devotion to me; āśhritaḥ—taking refuge; sarva-karma—of all actions; phala-tyāgam—to renounce the fruits; tataḥ—then; kuru—do; yata-ātma-vān—be situated in the self'),
('bf12ad55-b500-5f2c-932d-ade38a585961'::uuid, 12, 12, 481, 481, 'श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते।ध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्।।12.12।।', 'śhreyo hi jñānam abhyāsāj jñānād dhyānaṁ viśhiṣhyate
