('81905a09-cba3-5b8a-bce8-a43f0f1ceb77'::uuid, 15, 19, 570, 570, 'यो मामेवमसम्मूढो जानाति पुरुषोत्तमम्।स सर्वविद्भजति मां सर्वभावेन भारत।।15.19।।', 'yo mām evam asammūḍho jānāti puruṣhottamam
sa sarva-vid bhajati māṁ sarva-bhāvena bhārata', '[{"word":"yaḥ","meaning":"who"},{"word":"mām","meaning":"me"},{"word":"evam","meaning":"thus"},{"word":"asammūḍhaḥ","meaning":"without a doubt"},{"word":"jānāti","meaning":"know"},{"word":"puruṣha","meaning":"uttamam—the Supreme Divine Personality"},{"word":"saḥ","meaning":"they"},{"word":"sarva","meaning":"vit—those with complete knowledge"},{"word":"bhajati","meaning":"worship"},{"word":"mām","meaning":"me"},{"word":"sarva","meaning":"bhāvena—with one’s whole being"},{"word":"bhārata","meaning":"Arjun, the son of Bharat"}]'::jsonb, 'yaḥ—who; mām—me; evam—thus; asammūḍhaḥ—without a doubt; jānāti—know; puruṣha-uttamam—the Supreme Divine Personality; saḥ—they; sarva-vit—those with complete knowledge; bhajati—worship; mām—me; sarva-bhāvena—with one’s whole being; bhārata—Arjun, the son of Bharat'),
('868d3fea-ae92-5bd4-876e-8d49669892b8'::uuid, 15, 20, 571, 571, 'इति गुह्यतमं शास्त्रमिदमुक्तं मयाऽनघ।एतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत।।15.20।।', 'iti guhyatamaṁ śhāstram idam uktaṁ mayānagha
etad buddhvā buddhimān syāt kṛita-kṛityaśh cha bhārata', '[{"word":"iti","meaning":"these"},{"word":"guhya","meaning":"tamam—most secret"},{"word":"śhāstram","meaning":"Vedic scriptures"},{"word":"idam","meaning":"this"},{"word":"uktam","meaning":"spoken"},{"word":"mayā","meaning":"by me"},{"word":"anagha","meaning":"Arjun, the sinless one"},{"word":"etat","meaning":"this"},{"word":"buddhvā","meaning":"understanding"},{"word":"buddhi","meaning":"mān—enlightened"},{"word":"syāt","meaning":"one becomes"},{"word":"kṛita","meaning":"kṛityaḥ—who fulfills all that is to be accomplished"},{"word":"cha","meaning":"and"},{"word":"bhārata","meaning":"Arjun, the son of Bharat"}]'::jsonb, 'iti—these; guhya-tamam—most secret; śhāstram—Vedic scriptures; idam—this; uktam—spoken; mayā—by me; anagha—Arjun, the sinless one; etat—this; buddhvā—understanding; buddhi-mān—enlightened; syāt—one becomes; kṛita-kṛityaḥ—who fulfills all that is to be accomplished; cha—and; bhārata—Arjun, the son of Bharat'),
('edc758e4-b03b-5d3e-b77d-6119d6788ea5'::uuid, 16, 1, 572, 572, 'श्री भगवानुवाच

अभयं सत्त्वसंशुद्धिः ज्ञानयोगव्यवस्थितिः।

दानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम्।।16.1।।', 'śhrī-bhagavān uvācha
abhayaṁ sattva-sanśhuddhir jñāna-yoga-vyavasthitiḥ
dānaṁ damaśh cha yajñaśh cha svādhyāyas tapa ārjavam', '[{"word":"śhrī","meaning":"bhagavān uvācha—the Supreme Divine Personality said"},{"word":"abhayam","meaning":"fearlessness"},{"word":"sattva","meaning":"sanśhuddhiḥ—purity of mind"},{"word":"jñāna","meaning":"knowledge"},{"word":"yoga","meaning":"spiritual"},{"word":"vyavasthitiḥ","meaning":"steadfastness"},{"word":"dānam","meaning":"charity"},{"word":"damaḥ","meaning":"control of the senses"},{"word":"cha","meaning":"and"},{"word":"yajñaḥ","meaning":"performance of sacrifice"},{"word":"cha","meaning":"and"},{"word":"svādhyāyaḥ","meaning":"study of sacred books"},{"word":"tapaḥ","meaning":"austerity"},{"word":"ārjavam","meaning":"straightforwardness"}]'::jsonb, 'śhrī-bhagavān uvācha—the Supreme Divine Personality said; abhayam—fearlessness; sattva-sanśhuddhiḥ—purity of mind; jñāna—knowledge; yoga—spiritual; vyavasthitiḥ—steadfastness; dānam—charity; damaḥ—control of the senses; cha—and; yajñaḥ—performance of sacrifice; cha—and; svādhyāyaḥ—study of sacred books; tapaḥ—austerity; ārjavam—straightforwardness;')
