('0b69a6af-0b16-5a43-b214-2afd1081bb3f'::uuid, 16, 2, 573, 573, 'अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम्।दया भूतेष्वलोलुप्त्वं मार्दवं ह्रीरचापलम्।।16.2।।', 'ahinsā satyam akrodhas tyāgaḥ śhāntir apaiśhunam
dayā bhūteṣhv aloluptvaṁ mārdavaṁ hrīr achāpalam', '[{"word":"ahinsā","meaning":"non-violence"},{"word":"satyam","meaning":"truthfulness"},{"word":"akrodhaḥ","meaning":"absence of anger"},{"word":"tyāgaḥ","meaning":"renunciation"},{"word":"śhāntiḥ","meaning":"peacefulness"},{"word":"apaiśhunam","meaning":"restraint from fault-finding"},{"word":"dayā","meaning":"compassion"},{"word":"bhūteṣhu","meaning":"toward all living beings"},{"word":"aloluptvam","meaning":"absence of covetousness"},{"word":"mārdavam","meaning":"gentleness"},{"word":"hrīḥ","meaning":"modesty"},{"word":"achāpalam","meaning":"lack of fickleness"}]'::jsonb, 'ahinsā—non-violence; satyam—truthfulness; akrodhaḥ—absence of anger; tyāgaḥ—renunciation; śhāntiḥ—peacefulness; apaiśhunam—restraint from fault-finding; dayā—compassion; bhūteṣhu—toward all living beings; aloluptvam—absence of covetousness; mārdavam—gentleness; hrīḥ—modesty; achāpalam—lack of fickleness;'),
('33f7758d-ed19-5061-b841-ccca81125358'::uuid, 16, 3, 574, 574, 'तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता।

भवन्ति सम्पदं दैवीमभिजातस्य भारत।।16.3।।', 'tejaḥ kṣhamā dhṛitiḥ śhaucham adroho nāti-mānitā
bhavanti sampadaṁ daivīm abhijātasya bhārata', '[{"word":"tejaḥ","meaning":"vigor"},{"word":"kṣhamā","meaning":"forgiveness"},{"word":"dhṛitiḥ","meaning":"fortitude"},{"word":"śhaucham","meaning":"cleanliness"},{"word":"adrohaḥ","meaning":"bearing enmity toward none"},{"word":"na","meaning":"not"},{"word":"ati","meaning":"mānitā—absence of vanity"},{"word":"bhavanti","meaning":"are"},{"word":"sampadam","meaning":"qualities"},{"word":"daivīm","meaning":"godly"},{"word":"abhijātasya","meaning":"of those endowed with"},{"word":"bhārata","meaning":"scion of Bharat"}]'::jsonb, 'tejaḥ—vigor; kṣhamā—forgiveness; dhṛitiḥ—fortitude; śhaucham—cleanliness; adrohaḥ—bearing enmity toward none; na—not; ati-mānitā—absence of vanity; bhavanti—are; sampadam—qualities; daivīm—godly; abhijātasya—of those endowed with; bhārata—scion of Bharat'),
('8920b850-00f8-52fd-91a7-a444ad0cca0d'::uuid, 16, 4, 575, 575, 'दम्भो दर्पोऽभिमानश्च क्रोधः पारुष्यमेव च।अज्ञानं चाभिजातस्य पार्थ सम्पदमासुरीम्।।16.4।।', 'dambho darpo ’bhimānaśh cha krodhaḥ pāruṣhyam eva cha
ajñānaṁ chābhijātasya pārtha sampadam āsurīm', '[{"word":"dambhaḥ","meaning":"hypocrisy"},{"word":"darpaḥ","meaning":"arrogance"},{"word":"abhimānaḥ","meaning":"conceit"},{"word":"cha","meaning":"and"},{"word":"krodhaḥ","meaning":"anger"},{"word":"pāruṣhyam","meaning":"harshness"},{"word":"eva","meaning":"certainly"},{"word":"cha","meaning":"and"},{"word":"ajñānam","meaning":"ignorance"},{"word":"cha","meaning":"and"},{"word":"abhijātasya","meaning":"of those who possess"},{"word":"pārtha","meaning":"Arjun, the son of Pritha"},{"word":"sampadam","meaning":"qualities"},{"word":"āsurīm","meaning":"demoniac"}]'::jsonb, 'dambhaḥ—hypocrisy; darpaḥ—arrogance; abhimānaḥ—conceit; cha—and; krodhaḥ—anger; pāruṣhyam—harshness; eva—certainly; cha—and; ajñānam—ignorance; cha—and; abhijātasya—of those who possess; pārtha—Arjun, the son of Pritha; sampadam—qualities; āsurīm—demoniac'),
('35fbbcca-a025-5c87-81fc-78796730a723'::uuid, 16, 5, 576, 576, 'दैवी सम्पद्विमोक्षाय निबन्धायासुरी मता।मा शुचः सम्पदं दैवीमभिजातोऽसि पाण्डव।।16.5।।', 'daivī sampad vimokṣhāya nibandhāyāsurī matā
mā śhuchaḥ sampadaṁ daivīm abhijāto ’si pāṇḍava', '[{"word":"daivī","meaning":"divine"},{"word":"sampat","meaning":"qualities"},{"word":"vimokṣhāya","meaning":"toward liberation"},{"word":"nibandhāya","meaning":"to bondage"},{"word":"āsurī","meaning":"demoniac qualities"},{"word":"matā","meaning":"are considered"},{"word":"mā","meaning":"do not"},{"word":"śhuchaḥ","meaning":"grieve"},{"word":"sampadam","meaning":"virtues"},{"word":"daivīm","meaning":"saintly"},{"word":"abhijātaḥ","meaning":"born"},{"word":"asi","meaning":"you are"},{"word":"pāṇḍava","meaning":"Arjun, the son of Pandu"}]'::jsonb, 'daivī—divine; sampat—qualities; vimokṣhāya—toward liberation; nibandhāya—to bondage; āsurī—demoniac qualities; matā—are considered; mā—do not; śhuchaḥ—grieve; sampadam—virtues; daivīm—saintly; abhijātaḥ—born; asi—you are; pāṇḍava—Arjun, the son of Pandu'),
('07096359-2da5-5e15-83a8-fd2d6e801fde'::uuid, 16, 6, 577, 577, 'द्वौ भूतसर्गौ लोकेऽस्मिन् दैव आसुर एव च।दैवो विस्तरशः प्रोक्त आसुरं पार्थ मे श्रृणु।।16.6।।', 'dvau bhūta-sargau loke ’smin daiva āsura eva cha
daivo vistaraśhaḥ prokta āsuraṁ pārtha me śhṛiṇu', '[{"word":"dvau","meaning":"two"},{"word":"bhūta","meaning":"sargau—of created living beings"},{"word":"loke","meaning":"in the world"},{"word":"asmin","meaning":"this"},{"word":"daivaḥ","meaning":"divine"},{"word":"āsuraḥ","meaning":"demoniac"},{"word":"eva","meaning":"certainly"},{"word":"cha","meaning":"and"},{"word":"daivaḥ","meaning":"the divine"},{"word":"vistaraśhaḥ","meaning":"at great length"},{"word":"proktaḥ","meaning":"said"},{"word":"āsuram","meaning":"the demoniac"},{"word":"pārtha","meaning":"Arjun, the son of Pritha"},{"word":"me","meaning":"from me"},{"word":"śhṛiṇu","meaning":"hear"}]'::jsonb, 'dvau—two; bhūta-sargau—of created living beings; loke—in the world; asmin—this; daivaḥ—divine; āsuraḥ—demoniac; eva—certainly; cha—and; daivaḥ—the divine; vistaraśhaḥ—at great length; proktaḥ—said; āsuram—the demoniac; pārtha—Arjun, the son of Pritha; me—from me; śhṛiṇu—hear'),
('a2629eb4-66d9-5b6b-be63-e4a198d20cec'::uuid, 16, 7, 578, 578, 'प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः।न शौचं नापि चाचारो न सत्यं तेषु विद्यते।।16.7।।', 'pravṛittiṁ cha nivṛittiṁ cha janā na vidur āsurāḥ
na śhauchaṁ nāpi chāchāro na satyaṁ teṣhu vidyate', '[{"word":"pravṛittim","meaning":"proper actions"},{"word":"cha","meaning":"and"},{"word":"nivṛittim","meaning":"improper actions"},{"word":"cha","meaning":"and"},{"word":"janāḥ","meaning":"persons"},{"word":"na","meaning":"not"},{"word":"viduḥ","meaning":"comprehend"},{"word":"āsurāḥ","meaning":"those possessing demoniac nature"},{"word":"na","meaning":"neither"},{"word":"śhaucham","meaning":"purity"},{"word":"na","meaning":"nor"},{"word":"api","meaning":"even"},{"word":"cha","meaning":"and"},{"word":"āchāraḥ","meaning":"conduct"},{"word":"na","meaning":"nor"},{"word":"satyam","meaning":"truthfulness"},{"word":"teṣhu","meaning":"in them"},{"word":"vidyate","meaning":"exist"}]'::jsonb, 'pravṛittim—proper actions; cha—and; nivṛittim—improper actions; cha—and; janāḥ—persons; na—not; viduḥ—comprehend; āsurāḥ—those possessing demoniac nature; na—neither; śhaucham—purity; na—nor; api—even; cha—and; āchāraḥ—conduct; na—nor; satyam—truthfulness; teṣhu—in them; vidyate—exist'),
('38e94d6d-2816-5e1d-b72f-5913911805f8'::uuid, 16, 8, 579, 579, 'असत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम्।अपरस्परसम्भूतं किमन्यत्कामहैतुकम्।।16.8।।', 'asatyam apratiṣhṭhaṁ te jagad āhur anīśhvaram
