('f3652837-8d14-57ee-86e3-4d4cc027e172'::uuid, 16, 9, 580, 580, 'एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः।प्रभवन्त्युग्रकर्माणः क्षयाय जगतोऽहिताः।।16.9।।', 'etāṁ dṛiṣhṭim avaṣhṭabhya naṣhṭātmāno ’lpa-buddhayaḥ
prabhavanty ugra-karmāṇaḥ kṣhayāya jagato ’hitāḥ', '[{"word":"etām","meaning":"such"},{"word":"dṛiṣhṭim","meaning":"views"},{"word":"avaṣhṭabhya","meaning":"holding"},{"word":"naṣhṭa","meaning":"misdirected"},{"word":"ātmānaḥ","meaning":"souls"},{"word":"alpa","meaning":"buddhayaḥ—of small intellect"},{"word":"prabhavanti","meaning":"arise"},{"word":"ugra","meaning":"cruel"},{"word":"karmāṇaḥ","meaning":"actions"},{"word":"kṣhayāya","meaning":"destruction"},{"word":"jagataḥ","meaning":"of the world"},{"word":"ahitāḥ","meaning":"enemies"}]'::jsonb, 'etām—such; dṛiṣhṭim—views; avaṣhṭabhya—holding; naṣhṭa—misdirected; ātmānaḥ—souls; alpa-buddhayaḥ—of small intellect; prabhavanti—arise; ugra—cruel; karmāṇaḥ—actions; kṣhayāya—destruction; jagataḥ—of the world; ahitāḥ—enemies'),
('135218ed-a0df-5d01-9548-71a06f1aebe6'::uuid, 16, 10, 581, 581, 'काममाश्रित्य दुष्पूरं दम्भमानमदान्विताः।मोहाद्गृहीत्वासद्ग्राहान्प्रवर्तन्तेऽशुचिव्रताः।।16.10।।', 'kāmam āśhritya duṣhpūraṁ dambha-māna-madānvitāḥ
mohād gṛihītvāsad-grāhān pravartante ’śhuchi-vratāḥ', '[{"word":"kāmam","meaning":"lust"},{"word":"āśhritya","meaning":"harboring"},{"word":"duṣhpūram","meaning":"insatiable"},{"word":"dambha","meaning":"hypocrisy"},{"word":"māna","meaning":"arrogance"},{"word":"mada","meaning":"anvitāḥ—clinging to false tenets"},{"word":"mohāt","meaning":"the illusioned"},{"word":"gṛihītvā","meaning":"being attracted to"},{"word":"asat","meaning":"impermanent"},{"word":"grāhān","meaning":"things"},{"word":"pravartante","meaning":"they flourish"},{"word":"aśhuchi","meaning":"vratāḥ—with impure resolve"}]'::jsonb, 'kāmam—lust; āśhritya—harboring; duṣhpūram—insatiable; dambha—hypocrisy; māna—arrogance; mada-anvitāḥ—clinging to false tenets; mohāt—the illusioned; gṛihītvā—being attracted to; asat—impermanent; grāhān—things; pravartante—they flourish; aśhuchi-vratāḥ—with impure resolve'),
('630a4963-e675-5e8e-92df-1cd64fdc2d11'::uuid, 16, 11, 582, 582, 'चिन्तामपरिमेयां च प्रलयान्तामुपाश्रिताः।कामोपभोगपरमा एतावदिति निश्िचताः।।16.11।।', 'chintām aparimeyāṁ cha pralayāntām upāśhritāḥ
kāmopabhoga-paramā etāvad iti niśhchitāḥ', '[{"word":"chintām","meaning":"anxieties"},{"word":"aparimeyām","meaning":"endless"},{"word":"cha","meaning":"and"},{"word":"pralaya","meaning":"antām—until death"},{"word":"upāśhritāḥ","meaning":"taking refuge"},{"word":"kāma","meaning":"upabhoga—gratification of desires"},{"word":"paramāḥ","meaning":"the purpose of life"},{"word":"etāvat","meaning":"still"},{"word":"iti","meaning":"thus"},{"word":"niśhchitāḥ","meaning":"with complete assurance"}]'::jsonb, 'chintām—anxieties; aparimeyām—endless; cha—and; pralaya-antām—until death; upāśhritāḥ—taking refuge; kāma-upabhoga—gratification of desires; paramāḥ—the purpose of life; etāvat—still; iti—thus; niśhchitāḥ—with complete assurance'),
('6d1c1cab-de17-53a8-adb4-6671cb8f917d'::uuid, 16, 12, 583, 583, 'आशापाशशतैर्बद्धाः कामक्रोधपरायणाः।ईहन्ते कामभोगार्थमन्यायेनार्थसञ्चयान्।।16.12।।', 'āśhā-pāśha-śhatair baddhāḥ kāma-krodha-parāyaṇāḥ
