('fb03c842-cec5-57c7-ae6e-b51554e201c8'::uuid, 18, 50, 673, 673, 'सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे।समासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा।।18.50।।', 'siddhiṁ prāpto yathā brahma tathāpnoti nibodha me
samāsenaiva kaunteya niṣhṭhā jñānasya yā parā', '[{"word":"siddhim","meaning":"perfection"},{"word":"prāptaḥ","meaning":"attained"},{"word":"yathā","meaning":"how"},{"word":"brahma","meaning":"Brahman"},{"word":"tathā","meaning":"also"},{"word":"āpnoti","meaning":"attain"},{"word":"nibodha","meaning":"hear"},{"word":"me","meaning":"from me"},{"word":"samāsena","meaning":"briefly"},{"word":"eva","meaning":"indeed"},{"word":"kaunteya","meaning":"Arjun, the son of Kunti"},{"word":"niṣhṭhā","meaning":"firmly fixed"},{"word":"jñānasya","meaning":"of knowledge"},{"word":"yā","meaning":"which"},{"word":"parā","meaning":"transcendental"}]'::jsonb, 'siddhim—perfection; prāptaḥ—attained; yathā—how; brahma—Brahman; tathā—also; āpnoti—attain; nibodha—hear; me—from me; samāsena—briefly; eva—indeed; kaunteya—Arjun, the son of Kunti; niṣhṭhā—firmly fixed; jñānasya—of knowledge; yā—which; parā—transcendental'),
('48032393-d926-543e-8576-b517b228ccc3'::uuid, 18, 51, 674, 674, 'बुद्ध्या विशुद्धया युक्तो धृत्याऽऽत्मानं नियम्य च।शब्दादीन् विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च।।18.51।।', 'buddhyā viśhuddhayā yukto dhṛityātmānaṁ niyamya cha
śhabdādīn viṣhayāns tyaktvā rāga-dveṣhau vyudasya cha', '[{"word":"buddhyā","meaning":"intellect"},{"word":"viśhuddhayā","meaning":"purified"},{"word":"yuktaḥ","meaning":"endowed with"},{"word":"dhṛityā","meaning":"by determination"},{"word":"ātmānam","meaning":"the intellect"},{"word":"niyamya","meaning":"restraining"},{"word":"cha","meaning":"and"},{"word":"śhabda","meaning":"ādīn viṣhayān—sound and other objects of the senses"},{"word":"tyaktvā","meaning":"abandoning"},{"word":"rāga","meaning":"dveṣhau—attachment and aversion"},{"word":"vyudasya","meaning":"casting aside"},{"word":"cha","meaning":"and"}]'::jsonb, 'buddhyā—intellect; viśhuddhayā—purified; yuktaḥ—endowed with; dhṛityā—by determination; ātmānam—the intellect; niyamya—restraining; cha—and; śhabda-ādīn viṣhayān—sound and other objects of the senses; tyaktvā—abandoning; rāga-dveṣhau—attachment and aversion; vyudasya—casting aside; cha—and;'),
('d026c93b-cc7b-555b-8751-d933ebdb6b54'::uuid, 18, 52, 675, 675, 'विविक्तसेवी लघ्वाशी यतवाक्कायमानसः।ध्यानयोगपरो नित्यं वैराग्यं समुपाश्रितः।।18.52।।', 'vivikta-sevī laghv-āśhī yata-vāk-kāya-mānasaḥ
dhyāna-yoga-paro nityaṁ vairāgyaṁ samupāśhritaḥ', '[{"word":"vivikta","meaning":"sevī—relishing solitude"},{"word":"laghu","meaning":"āśhī—eating light"},{"word":"yata","meaning":"controls"},{"word":"vāk","meaning":"speech"},{"word":"kāya","meaning":"body"},{"word":"mānasaḥ","meaning":"and mind"},{"word":"dhyāna","meaning":"yoga-paraḥ—engaged in meditation"},{"word":"nityam","meaning":"always"},{"word":"vairāgyam","meaning":"dispassion"},{"word":"samupāśhritaḥ","meaning":"having taken shelter of"}]'::jsonb, 'vivikta-sevī—relishing solitude; laghu-āśhī—eating light; yata—controls; vāk—speech; kāya—body; mānasaḥ—and mind; dhyāna-yoga-paraḥ—engaged in meditation; nityam—always; vairāgyam—dispassion; samupāśhritaḥ—having taken shelter of;'),
('c66eded3-fe89-504d-a33e-0bc722b8c32e'::uuid, 18, 53, 676, 676, 'अहङ्कारं बलं दर्पं कामं क्रोधं परिग्रहम्।विमुच्य निर्ममः शान्तो ब्रह्मभूयाय कल्पते।।18.53।।', 'ahankāraṁ balaṁ darpaṁ kāmaṁ krodhaṁ parigraham
vimuchya nirmamaḥ śhānto brahma-bhūyāya kalpate', '[{"word":"ahankāram","meaning":"egotism"},{"word":"balam","meaning":"violence"},{"word":"darpam","meaning":"arrogance"},{"word":"kāmam","meaning":"desire"},{"word":"krodham","meaning":"anger"},{"word":"parigraham","meaning":"selfishness"},{"word":"vimuchya","meaning":"being freed from"},{"word":"nirmamaḥ","meaning":"without possessiveness of property"},{"word":"śhāntaḥ","meaning":"peaceful"},{"word":"brahma","meaning":"bhūyāya—union with Brahman"},{"word":"kalpate","meaning":"is fit"}]'::jsonb, 'ahankāram—egotism; balam—violence; darpam—arrogance; kāmam—desire; krodham—anger; parigraham—selfishness; vimuchya—being freed from; nirmamaḥ—without possessiveness of property; śhāntaḥ—peaceful; brahma-bhūyāya—union with Brahman; kalpate—is fit'),
('0bc23035-867c-5f09-a058-26486df3c47d'::uuid, 18, 54, 677, 677, 'ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति।समः सर्वेषु भूतेषु मद्भक्तिं लभते पराम्।।18.54।।', 'brahma-bhūtaḥ prasannātmā na śhochati na kāṅkṣhati
samaḥ sarveṣhu bhūteṣhu mad-bhaktiṁ labhate parām', '[{"word":"brahma","meaning":"bhūtaḥ—one situated in Brahman"},{"word":"prasanna","meaning":"ātmā—mentally serene"},{"word":"na","meaning":"neither"},{"word":"śhochati","meaning":"grieving"},{"word":"na","meaning":"nor"},{"word":"kāṅkṣhati","meaning":"desiring"},{"word":"samaḥ","meaning":"equitably disposed"},{"word":"sarveṣhu","meaning":"toward all"},{"word":"bhūteṣhu","meaning":"living beings"},{"word":"mat","meaning":"bhaktim—devotion to me"},{"word":"labhate","meaning":"attains"},{"word":"parām","meaning":"supreme"}]'::jsonb, 'brahma-bhūtaḥ—one situated in Brahman; prasanna-ātmā—mentally serene; na—neither; śhochati—grieving; na—nor; kāṅkṣhati—desiring; samaḥ—equitably disposed; sarveṣhu—toward all; bhūteṣhu—living beings; mat-bhaktim—devotion to me; labhate—attains; parām—supreme'),
('1859b3b0-f11c-5156-a147-1d8e7e65f05a'::uuid, 18, 55, 678, 678, 'भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः।ततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम्।।18.55।।', 'bhaktyā mām abhijānāti yāvān yaśh chāsmi tattvataḥ
tato māṁ tattvato jñātvā viśhate tad-anantaram', '[{"word":"bhaktyā","meaning":"by loving devotion"},{"word":"mām","meaning":"me"},{"word":"abhijānāti","meaning":"one comes to know"},{"word":"yāvān","meaning":"as much as"},{"word":"yaḥ cha asmi","meaning":"as I am"},{"word":"tattvataḥ","meaning":"in truth"},{"word":"tataḥ","meaning":"then"},{"word":"mām","meaning":"me"},{"word":"tattvataḥ","meaning":"in truth"},{"word":"jñātvā","meaning":"having known"},{"word":"viśhate","meaning":"enters"},{"word":"tat","meaning":"anantaram—thereafter"}]'::jsonb, 'bhaktyā—by loving devotion; mām—me; abhijānāti—one comes to know; yāvān—as much as; yaḥ cha asmi—as I am; tattvataḥ—in truth; tataḥ—then; mām—me; tattvataḥ—in truth; jñātvā—having known; viśhate—enters; tat-anantaram—thereafter'),
('6cb2b09a-1dd6-5e8c-8fe8-e0cd16687f3d'::uuid, 18, 56, 679, 679, 'सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः।मत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम्।।18.56।।', 'sarva-karmāṇy api sadā kurvāṇo mad-vyapāśhrayaḥ
mat-prasādād avāpnoti śhāśhvataṁ padam avyayam', '[{"word":"sarva","meaning":"all"},{"word":"karmāṇi","meaning":"actions"},{"word":"api","meaning":"though"},{"word":"sadā","meaning":"always"},{"word":"kurvāṇaḥ","meaning":"performing"},{"word":"mat","meaning":"vyapāśhrayaḥ—take full refuge in me"},{"word":"mat","meaning":"prasādāt—by my grace"},{"word":"avāpnoti","meaning":"attain"},{"word":"śhāśhvatam","meaning":"the eternal"},{"word":"padam","meaning":"abode"},{"word":"avyayam","meaning":"imperishable"}]'::jsonb, 'sarva—all; karmāṇi—actions; api—though; sadā—always; kurvāṇaḥ—performing; mat-vyapāśhrayaḥ—take full refuge in me; mat-prasādāt—by my grace; avāpnoti—attain; śhāśhvatam—the eternal; padam—abode; avyayam—imperishable'),
('31a3a9f0-a75d-5b36-8f42-12ccbe43c915'::uuid, 18, 57, 680, 680, 'चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः।बुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव।।18.57।।', 'chetasā sarva-karmāṇi mayi sannyasya mat-paraḥ
buddhi-yogam upāśhritya mach-chittaḥ satataṁ bhava', '[{"word":"chetasā","meaning":"by consciousness"},{"word":"sarva","meaning":"karmāṇi—every activity"},{"word":"mayi","meaning":"to me"},{"word":"sannyasya","meaning":"dedicating"},{"word":"mat","meaning":"paraḥ—having me as the supreme goal"},{"word":"buddhi","meaning":"yogam—having the intellect united with God"},{"word":"upāśhritya","meaning":"taking shelter of"},{"word":"mat","meaning":"chittaḥ—consciousness absorbed in me"},{"word":"satatam","meaning":"always"},{"word":"bhava","meaning":"be"}]'::jsonb, 'chetasā—by consciousness; sarva-karmāṇi—every activity; mayi—to me; sannyasya—dedicating; mat-paraḥ—having me as the supreme goal; buddhi-yogam—having the intellect united with God; upāśhritya—taking shelter of; mat-chittaḥ—consciousness absorbed in me; satatam—always; bhava—be'),
('a880de33-b6ec-5514-b87f-ed0a6ebda995'::uuid, 18, 58, 681, 681, 'मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि।अथ चेत्त्वमहङ्कारान्न श्रोष्यसि विनङ्क्ष्यसि।।18.58।।', 'mach-chittaḥ sarva-durgāṇi mat-prasādāt tariṣhyasi
atha chet tvam ahankārān na śhroṣhyasi vinaṅkṣhyasi', '[{"word":"mat","meaning":"chittaḥ—by always remembering me"},{"word":"sarva","meaning":"all"},{"word":"durgāṇi","meaning":"obstacles"},{"word":"mat","meaning":"prasādāt—by my grace"},{"word":"tariṣhyasi","meaning":"you shall overcome"},{"word":"atha","meaning":"but"},{"word":"chet","meaning":"if"},{"word":"tvam","meaning":"you"},{"word":"ahankārāt","meaning":"due to pride"},{"word":"na śhroṣhyasi","meaning":"do not listen"},{"word":"vinaṅkṣhyasi","meaning":"you will perish"}]'::jsonb, 'mat-chittaḥ—by always remembering me; sarva—all; durgāṇi—obstacles; mat-prasādāt—by my grace; tariṣhyasi—you shall overcome; atha—but; chet—if; tvam—you; ahankārāt—due to pride; na śhroṣhyasi—do not listen; vinaṅkṣhyasi—you will perish'),
('6292110c-df66-5538-a07f-4d41c3089dc1'::uuid, 18, 59, 682, 682, 'यदहङ्कारमाश्रित्य न योत्स्य इति मन्यसे।मिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति।।18.59।।', 'yad ahankāram āśhritya na yotsya iti manyase
mithyaiṣha vyavasāyas te prakṛitis tvāṁ niyokṣhyati', '[{"word":"yat","meaning":"if"},{"word":"ahankāram","meaning":"motivated by pride"},{"word":"āśhritya","meaning":"taking shelter"},{"word":"na yotsye","meaning":"I shall not fight"},{"word":"iti","meaning":"thus"},{"word":"manyase","meaning":"you think"},{"word":"mithyā eṣhaḥ","meaning":"this is all false"},{"word":"vyavasāyaḥ","meaning":"determination"},{"word":"te","meaning":"your"},{"word":"prakṛitiḥ","meaning":"material nature"},{"word":"tvām","meaning":"you"},{"word":"niyokṣhyati","meaning":"will engage"}]'::jsonb, 'yat—if; ahankāram—motivated by pride; āśhritya—taking shelter; na yotsye—I shall not fight; iti—thus; manyase—you think; mithyā eṣhaḥ—this is all false; vyavasāyaḥ—determination; te—your; prakṛitiḥ—material nature; tvām—you; niyokṣhyati—will engage'),
('b45448ce-f5b2-5652-8138-6282c3bb5366'::uuid, 18, 60, 683, 683, 'स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा।कर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत्।।18.60।।', 'swbhāva-jena kaunteya nibaddhaḥ svena karmaṇā
kartuṁ nechchhasi yan mohāt kariṣhyasy avaśho ’pi tat', '[{"word":"swabhāva","meaning":"jena—born of one’s own material nature"},{"word":"kaunteya","meaning":"Arjun, the son of Kunti"},{"word":"nibaddhaḥ","meaning":"bound"},{"word":"svena","meaning":"by your own"},{"word":"karmaṇā","meaning":"actions"},{"word":"kartum","meaning":"to do"},{"word":"na","meaning":"not"},{"word":"ichchhasi","meaning":"you wish"},{"word":"yat","meaning":"which"},{"word":"mohāt","meaning":"out of delusion"},{"word":"kariṣhyasi","meaning":"you will do"},{"word":"avaśhaḥ","meaning":"helplessly"},{"word":"api","meaning":"even though"},{"word":"tat","meaning":"that"}]'::jsonb, 'swabhāva-jena—born of one’s own material nature; kaunteya—Arjun, the son of Kunti; nibaddhaḥ—bound; svena—by your own; karmaṇā—actions; kartum—to do; na—not; ichchhasi—you wish; yat—which; mohāt—out of delusion; kariṣhyasi—you will do; avaśhaḥ—helplessly; api—even though; tat—that'),
('87f3e1b1-5a5d-5c16-834b-afe93999beaa'::uuid, 18, 61, 684, 684, 'ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति।भ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया।।18.61।।', 'īśhvaraḥ sarva-bhūtānāṁ hṛid-deśhe ‘rjuna tiṣhṭhati
bhrāmayan sarva-bhūtāni yantrārūḍhāni māyayā', '[{"word":"īśhvaraḥ","meaning":"the Supreme Lord"},{"word":"sarva","meaning":"bhūtānām—in all living being"},{"word":"hṛit","meaning":"deśhe—in the hearts"},{"word":"arjuna","meaning":"Arjun"},{"word":"tiṣhṭhati","meaning":"dwells"},{"word":"bhrāmayan","meaning":"causing to wander"},{"word":"sarva","meaning":"bhūtāni—all living beings"},{"word":"yantra ārūḍhani","meaning":"seated on a machine"},{"word":"māyayā","meaning":"made of the material energy"}]'::jsonb, 'īśhvaraḥ—the Supreme Lord; sarva-bhūtānām—in all living being; hṛit-deśhe—in the hearts; arjuna—Arjun; tiṣhṭhati—dwells; bhrāmayan—causing to wander; sarva-bhūtāni—all living beings; yantra ārūḍhani—seated on a machine; māyayā—made of the material energy'),
('f0152c09-3827-5ad6-bc79-50ce2f80afc8'::uuid, 18, 62, 685, 685, 'तमेव शरणं गच्छ सर्वभावेन भारत।तत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम्।।18.62।।', 'tam eva śharaṇaṁ gachchha sarva-bhāvena bhārata
tat-prasādāt parāṁ śhāntiṁ sthānaṁ prāpsyasi śhāśhvatam', '[{"word":"tam","meaning":"unto him"},{"word":"eva","meaning":"only"},{"word":"śharaṇam gachchha","meaning":"surrender"},{"word":"sarva","meaning":"bhāvena—whole-heartedly"},{"word":"bhārata","meaning":"Arjun, the son of Bharat"},{"word":"tat","meaning":"prasādāt—by his grace"},{"word":"parām","meaning":"supreme"},{"word":"śhāntim","meaning":"peace"},{"word":"sthānam","meaning":"the abode"},{"word":"prāpsyasi","meaning":"you will attain"},{"word":"śhāśhvatam","meaning":"eternal"}]'::jsonb, 'tam—unto him; eva—only; śharaṇam gachchha—surrender; sarva-bhāvena—whole-heartedly; bhārata—Arjun, the son of Bharat; tat-prasādāt—by his grace; parām—supreme; śhāntim—peace; sthānam—the abode; prāpsyasi—you will attain; śhāśhvatam—eternal'),
('e063c739-2aa6-5e73-80fa-1feeff5aa04e'::uuid, 18, 63, 686, 686, 'इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया।विमृश्यैतदशेषेण यथेच्छसि तथा कुरु।।18.63।।', 'iti te jñānam ākhyātaṁ guhyād guhyataraṁ mayā
vimṛiśhyaitad aśheṣheṇa yathechchhasi tathā kuru', '[{"word":"iti","meaning":"thus"},{"word":"te","meaning":"to you"},{"word":"jñānam","meaning":"knowledge"},{"word":"ākhyātam","meaning":"explained"},{"word":"guhyāt","meaning":"than secret knowledge"},{"word":"guhya","meaning":"taram—still more secret knowledge"},{"word":"mayā","meaning":"by me"},{"word":"vimṛiśhya","meaning":"pondering"},{"word":"etat","meaning":"on this"},{"word":"aśheṣheṇa","meaning":"completely"},{"word":"yathā","meaning":"as"},{"word":"ichchhasi","meaning":"you wish"},{"word":"tathā","meaning":"so"},{"word":"kuru","meaning":"do"}]'::jsonb, 'iti—thus; te—to you; jñānam—knowledge; ākhyātam—explained; guhyāt—than secret knowledge; guhya-taram—still more secret knowledge; mayā—by me; vimṛiśhya—pondering; etat—on this; aśheṣheṇa—completely; yathā—as; ichchhasi—you wish; tathā—so; kuru—do'),
('b733a82a-53e5-5059-98a4-c4cfbe336026'::uuid, 18, 64, 687, 687, 'सर्वगुह्यतमं भूयः श्रृणु मे परमं वचः।इष्टोऽसि मे दृढमिति ततो वक्ष्यामि ते हितम्।।18.64।।', 'sarva-guhyatamaṁ bhūyaḥ śhṛiṇu me paramaṁ vachaḥ
iṣhṭo ‘si me dṛiḍham iti tato vakṣhyāmi te hitam', '[{"word":"sarva","meaning":"guhya-tamam—the most confidential of all"},{"word":"bhūyaḥ","meaning":"again"},{"word":"śhṛiṇu","meaning":"hear"},{"word":"me","meaning":"by me"},{"word":"paramam","meaning":"supreme"},{"word":"vachaḥ","meaning":"instruction"},{"word":"iṣhṭaḥ asi","meaning":"you are dear"},{"word":"me","meaning":"to me"},{"word":"dṛiḍham","meaning":"very"},{"word":"iti","meaning":"thus"},{"word":"tataḥ","meaning":"because"},{"word":"vakṣhyāmi","meaning":"I am speaking"},{"word":"te","meaning":"for your"},{"word":"hitam","meaning":"benefit"}]'::jsonb, 'sarva-guhya-tamam—the most confidential of all; bhūyaḥ—again; śhṛiṇu—hear; me—by me; paramam—supreme; vachaḥ—instruction; iṣhṭaḥ asi—you are dear; me—to me; dṛiḍham—very; iti—thus; tataḥ—because; vakṣhyāmi—I am speaking; te—for your; hitam—benefit'),
('c65e783d-5615-590a-9499-b901df609df1'::uuid, 18, 65, 688, 688, 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।मामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे।।18.65।।', 'man-manā bhava mad-bhakto mad-yājī māṁ namaskuru
